export const FAWAID_ITEMS = [
  { text: "إنما بُعثت لأتمم مكارم الأخلاق، وهذا من مكارم الأخلاق التي أمر بها الشرع. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "رواه البيهقي — صحيح الألباني", author_name: "شعب الإيمان" },
  { text: "الحزن على الماضي مضيعة للحاضر، وهذا من مكارم الأخلاق التي أمر بها الشرع. فليُلزم المسلم العمل بما علم. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الأخلاق", source: "قاعدة نبوية — ابن القيم: مدارج السالكين", author_name: "ابن قيم الجوزية" },
  { text: "العلم النافع يرفع صاحبه ويثمر العمل؛ قال ﷺ: «من سلك طريقًا يلتمس فيه علمًا سهّل الله له به طريقًا إلى الجنة» — مسلم. وأما ألفاظ «العالم والمتعلم شريكان…» فضعيفة فلا يُستقل بها.", category: "طلب العلم", source: "مسلم ٢٦٩٩؛ ضعّف أهل التحقيق الألفاظ المشهورة الأخرى", author_name: "صحيح البخاري" },
  { text: "قيدوا العلم بالكتاب؛ فالكتابة تصون الحفظ من النسيان، وهذا من آداب طلب العلم وأصوله التي يُرجى بها نفع العلم. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "أثر موقوف — رواه الدارمي وابن أبي شيبة، وصححه الحاكم في المستدرك", author_name: "عمر بن الخطاب" },
  { text: "طلب العلم نافع للدنيا والآخرة؛ يُنسب للشافعي: «من أراد الدنيا فعليه بالعلم…» وهو قول مأثور بلا إسناد متصل يُعوَّل عليه، فيُذكر أدباً لا حديثاً. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "طلب العلم", source: "نسبة مشهورة للشافعي بلا إسناد متصل معتمد", author_name: "يُنسب للإمام الشافعي" },
  { text: "فوالله لأن يهدي الله بك رجلاً واحداً خير لك من حمر النعم، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "بلّغوا عني ولو آية؛ فالعلم يزكو بالتبليغ ولو قلّ، وهذا من آداب الدعوة إلى الله بالحكمة والموعظة الحسنة. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الدعوة", source: "رواه البخاري", author_name: "صحيح البخاري" },
  { text: "تأديب الولد وتعليمه من أعظم الحقوق؛ قال ﷺ: «مروا أولادكم بالصلاة لسبع» — أبو داود، حسّنه الألباني. وأما لفظ «لأن يؤدب أحدكم ولده خير من أن يتصدق بصاع» فضعيف فلا يُستقل به.", category: "التربية", source: "أبو داود ٤٩٥ حسّنه الألباني؛ ضعّف الترمذي وغيره لفظ «خير من أن يتصدق بصاع»", author_name: "صحيح البخاري" },
  { text: "حق الولد على والده أن يحسن اسمه ويحسن تربيته، وهذا من أصول التربية الإسلامية التي يُنشأ عليها الولد. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التربية", source: "رواه البيهقي", author_name: "شعب الإيمان" },
  { text: "العناية بالعربية خدمة لفهم ألفاظ القرآن؛ والمعنى مقرَّر عند أهل العلم. وأما المرفوع «أعربوا القرآن والتمسوا غرائبه» فضعيف فلا يُستقل به. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "اللغة", source: "معنى علمي مقرَّر؛ ضعّف المحدّثون لفظ «أعربوا القرآن»", author_name: "صحيح البخاري" },
  { text: "العناية بالعربية تعين على فهم القرآن والسنة؛ ولا يُحتج في ذلك بحديث موضوع، وهذا من فوائد العناية بلسان العرب وفهم كلام الله. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "اللغة", source: "حديث «أحبوا العرب لثلاث» موضوع باتفاق النقاد — لا يُروى", author_name: "صحيح البخاري" },
  { text: "من أحبّ للمسلمين ما يُحب لنفسه فقد كمل إيمانه، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "لا يؤمن أحدكم حتى يحب لأخيه ما يحب لنفسه — متفق عليه", author_name: "صحيح البخاري" },
  { text: "أفضل الإيمان أن تعلم أن الله معك أينما كنت، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه الطبراني — حسنه الألباني", author_name: "المعجم الكبير" },
  { text: "من مات وهو يعلم أنه لا إله إلا الله دخل الجنة، وهذا من أصول الاعتقاد التي يُبنى عليها إيمان المسلم وعمله. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "التوكل على الله لا يعني ترك الأسباب؛ قال ﷺ للأعرابي: «اعقلها وتوكل» — الترمذي ٢٥١٧، حسّنه الألباني. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "العقيدة", source: "الترمذي ٢٥١٧ — حسن", author_name: "صحيح البخاري" },
  { text: "كفى بالمرء كذباً أن يُحدّث بكل ما سمع، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه مسلم في مقدمة صحيحه", author_name: "صحيح مسلم" },
  { text: "المسلم من سلم المسلمون من لسانه ويده، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "متفق عليه", author_name: "صحيح البخاري" },
  { text: "لا تحقرن من المعروف شيئاً ولو أن تلقى أخاك بوجه طلق، وهذا من هدي النبي ﷺ الذي يجب على المسلم معرفته والعمل به. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الحديث", source: "رواه مسلم", author_name: "صحيح مسلم" },
  { text: "القرآن الكريم نزل بلغة العرب ليُفهم ويُعمل به، فمن تدبّره وجد فيه دواء لكل داء، وهذا بيان يُعين على فهم مراد الله في كتابه. كما دلّ عليه الكتاب والسنة.", category: "التفسير", source: "وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ — الإسراء: 82", author_name: "تفسير ابن كثير" },
  { text: "الفاتحة أم القرآن لأنها جمعت أصول الدين: التوحيد، والعبادة، والطلب، والتوسل، وهذا بيان يُعين على فهم مراد الله في كتابه. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "تفسير ابن كثير — الفاتحة", author_name: "ابن كثير" },
  { text: "آية الكرسي أعظم آية في القرآن لاشتمالها على صفات الله العليا، وهذا بيان يُعين على فهم مراد الله في كتابه. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "التفسير", source: "رواه مسلم — كتاب صلاة المسافرين", author_name: "صحيح مسلم" },
  { text: "لا ضرر ولا ضرار — قاعدة فقهية جامعة تمنع كل أذى للنفس أو الغير، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما ثبت في السنة الصحيحة. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "رواه ابن ماجه وصححه الألباني", author_name: "قواعد الفقه الإسلامي" },
  { text: "المشقة تجلب التيسير — رفع الحرج من أبرز خصائص الشريعة الإسلامية، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. كما دلّ عليه الكتاب والسنة.", category: "الفقه", source: "وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ — الحج: 78", author_name: "الأشباه والنظائر — السيوطي" },
  { text: "الأمور بمقاصدها — فالعبرة في الأحكام الشرعية بالنوايا والمآلات، وهذا أصل يُسترشد به في فهم الأحكام الشرعية وتطبيقها. — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "الفقه", source: "القاعدة الأولى من القواعد الخمس الكبرى", author_name: "المجلة الأحكام العدلية" },
  { text: "الهجرة النبوية درس في الصبر والتخطيط؛ فما أسس النبي ﷺ دولة إلا بعد 13 سنة من الدعوة (3 سنوات سرًا و10 سنوات جهرًا). — وهذا مما يستحق التأمل والعمل به في السلوك والعبادة.", category: "السيرة", source: "السيرة النبوية — ابن هشام وابن كثير", author_name: "ابن هشام" }
];
